contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address recipient) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(recipient == address(this));
        uint balBefore = address(this).balance;
        c.withdrawReward(recipient); if (__ESBMC_reverted()) return;
        assert(address(this).balance == balBefore);
    }
    receive() external payable {}
}

